  var dn = !!sc.down, stg = opt(sc, "stagger", 0.3), HH = vh(540, 440), base = dn ? vh(660, 300) : vh(1180, 800), mx = opt(sc, "max", 0), dec = opt(sc, "decimals", 0), ls = [];
